'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),{JSDOM}=require('jsdom');
const src=fs.readFileSync('ratib-feedback-3.6.149.js','utf8');
const dom=new JSDOM('<div id="notificationSoundCard"><div class="settings-accordion-body"></div></div><div id="toastStack"></div>',{url:'https://ratib.test',runScripts:'outside-only'});
const w=dom.window,calls=[];let audio=0,vibes=0;
w.RatibNative={playSystemSound:kind=>{calls.push(kind);return true;}};
w.AudioContext=class{constructor(){audio++;throw Error('Native must not synthesize media sound');}};
Object.defineProperty(w.navigator,'vibrate',{value:()=>{vibes++;return true;}});
w.eval(src);w.document.dispatchEvent(new w.Event('DOMContentLoaded'));
const f=w.RatibFeedback;
for(const kind of ['tap','save','warning','error','reminder','urgent','critical'])assert(f.play(kind,'',true));
assert.deepEqual(calls,['tap','save','warning','error','reminder','urgent','critical']);assert.equal(audio,0);
f.write({volume:'low',style:'soft'});f.play('tap','',true);assert.equal(calls.at(-1),'tap','App gain never reaches native sound');
const count=calls.length;f.write({master:false});assert.equal(f.play('tap','',true),false);assert.equal(f.allowReminderSound(),false);assert.equal(calls.length,count);
f.write({master:true,tapCue:'vibration'});f.play('tap','',true);assert.equal(calls.length,count);assert(vibes>0);
f.write({tapCue:'sound'});w.RatibNative.playSystemSound=()=>{throw Error('unavailable');};f.play('tap','',true);assert.equal(audio,0,'A muted/unavailable native sound never falls back to media');
w.RatibNative.playSystemSound=kind=>{calls.push(kind);return true;};
w.Notification={permission:'granted'};const before=calls.length;
f.reminder({title:'fixture'},()=>-1,()=>{},()=>{},()=>{},()=>{},()=>[]);assert.equal(calls.length,before,'System notification owns actual reminder audio once');
w.Date.now=()=>Date.now()+3000;w.Notification.permission='denied';f.reminder({title:'fixture'},()=>-1,()=>{},()=>{},()=>{},()=>{},()=>[]);assert.equal(calls.at(-1),'reminder','Denied permission retains foreground default notification sound');
for(const key of ['volume','style'])assert(w.document.querySelector('[data-feedback-select="'+key+'"]').closest('.ratib-feedback-select-row').hidden);
const java=fs.readFileSync('android/app/src/main/java/dev/ratib/android/MainActivity.java','utf8');
assert(java.includes('manager.playSoundEffect(android.media.AudioManager.FX_KEY_CLICK);'));
assert(!java.includes('SoundPool'));assert(!java.includes('setStreamVolume('));assert(!java.includes('setRingerMode('));
assert(java.includes('TYPE_NOTIFICATION'));assert(java.includes('DEFAULT_NOTIFICATION_URI'));assert(java.includes('INTERRUPTION_FILTER_ALL'));
const bridge=fs.readFileSync('android/web/ratib-native-bridge.js','utf8');assert(bridge.includes('allowReminderSound?.()===false'));
w.close();console.log('PASS system audio: native categories, system gain, mute, vibration-only, no synthetic fallback, single reminder and truthful settings');
